package com.yangbin.yangbinaiagent;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.yangbin.yangbinaiagent.governance.ModelGovernance;
import com.yangbin.yangbinaiagent.security.UserContext;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.ai.chat.model.*;
import org.springframework.ai.chat.metadata.*;
import org.springframework.ai.chat.messages.AssistantMessage;
import org.springframework.ai.chat.prompt.*;
import reactor.core.publisher.Flux;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class ModelGovernanceTest {
 @TempDir Path dir;
 final ObjectMapper json=new ObjectMapper();
 final UserContext.User a=new UserContext.User("a".repeat(32),"user"),b=new UserContext.User("b".repeat(32),"user");
 final Clock clock=Clock.fixed(Instant.parse("2026-10-20T10:00:00Z"),ZoneOffset.UTC);
 ModelGovernance create(int account,int global,int requests,long tokens){return new ModelGovernance(json,dir,clock,new ModelGovernance.Limits(account,global,requests,tokens,128));}
 ChatResponse response(Integer input,Integer output){return new ChatResponse(List.of(new Generation(new AssistantMessage("fixture"))),ChatResponseMetadata.builder().usage(new DefaultUsage(input,output)).build());}
 @Test void boundsAccountAndGlobalConcurrencyAndReleasesOnFinish(){var g=create(1,2,10,1000);var first=UserContext.call(a,()->g.reserve("openai","fixture",100));assertThatThrownBy(()->UserContext.call(a,()->g.reserve("openai","fixture",100))).isInstanceOf(ModelGovernance.Denied.class);var second=UserContext.call(b,()->g.reserve("openai","fixture",100));assertThatThrownBy(()->UserContext.call(UserContext.ADMIN,()->g.reserve("openai","fixture",100))).isInstanceOf(ModelGovernance.Denied.class);g.finish(first,10L,20L,"SUCCEEDED");UserContext.call(a,()->g.reserve("openai","fixture",100));g.finish(second,null,null,"UNKNOWN");}
 @Test void concurrentAdmissionNeverOversubscribes()throws Exception{var g=create(2,2,100,10000);var start=new CountDownLatch(1);var winners=new CopyOnWriteArrayList<ModelGovernance.Lease>();try(var pool=Executors.newFixedThreadPool(12)){var jobs=new ArrayList<Future<?>>();for(int i=0;i<12;i++)jobs.add(pool.submit(()->{try{start.await();winners.add(UserContext.call(a,()->g.reserve("openai","fixture",100)));}catch(ModelGovernance.Denied expected){}catch(InterruptedException e){Thread.currentThread().interrupt();}}));start.countDown();for(var job:jobs)job.get();}assertThat(winners).hasSize(2);}
 @Test void knownUsageIsSeparateFromConservativeQuotaAcrossRestart(){var g=create(2,2,10,500);try(var scope=UserContext.open(a)){var one=g.reserve("openai","fixture",200);g.finish(one,10L,20L,"SUCCEEDED");var two=g.reserve("openai","fixture",200);g.finish(two,null,null,"SUCCEEDED");var restarted=create(2,2,10,500);assertThat(restarted.summary().knownTokens()).isEqualTo(30);assertThat(restarted.summary().unknownUsageRequests()).isEqualTo(1);assertThat(restarted.summary().budgetChargedTokens()).isEqualTo(400);assertThat(restarted.events().getFirst().inputTokens()).isNull();assertThatThrownBy(()->restarted.reserve("openai","fixture",300)).isInstanceOf(ModelGovernance.Denied.class);}}
 @Test void restartMarksInflightUnknownWithoutRefund(){var g=create(2,2,10,500);try(var scope=UserContext.open(a)){g.reserve("openai","fixture",200);var restored=create(2,2,10,500);assertThat(restored.events().getFirst().status()).isEqualTo("UNKNOWN");assertThat(restored.summary().active()).isZero();assertThat(restored.summary().budgetChargedTokens()).isEqualTo(200);}}
 @Test void requestsAreBoundedEvenWhenProviderReportsZeroTokens(){var g=create(2,2,1,500);try(var scope=UserContext.open(a)){var lease=g.reserve("openai","fixture",100);g.finish(lease,0L,0L,"SUCCEEDED");assertThatThrownBy(()->g.reserve("openai","fixture",100)).isInstanceOf(ModelGovernance.Denied.class).hasMessageContaining("次数");}}
 @Test void accountsCannotSeeOtherUsageAndEvents(){var g=create(2,2,10,500);UserContext.call(a,()->g.reserve("openai","fixture",100));try(var scope=UserContext.open(b)){assertThat(g.events()).isEmpty();assertThat(g.summary().requests()).isZero();assertThat(g.summary().globalActive()).isEqualTo(-1);}try(var scope=UserContext.open(UserContext.ADMIN)){assertThat(g.summary().globalActive()).isEqualTo(1);}}
 @Test void invalidAndOversizedReservationsNeverCallUpstream(){var g=create(2,2,10,500);AtomicInteger calls=new AtomicInteger();ChatModel model=g.govern(prompt->{calls.incrementAndGet();return response(1,1);},"openai","fixture");try(var scope=UserContext.open(a)){assertThatThrownBy(()->g.reserve("openai","fixture",0)).isInstanceOf(ModelGovernance.Denied.class);assertThatThrownBy(()->model.call(new Prompt("large"))).isInstanceOf(ModelGovernance.Denied.class);assertThat(calls).hasValue(0);}}
 @Test void corruptedLedgerFailsClosed()throws Exception{Path file=dir.resolve(a.id()).resolve("2026-10-20.json");Files.createDirectories(file.getParent());Files.writeString(file,"broken");var g=create(2,2,10,500);assertThatThrownBy(()->UserContext.call(a,()->g.reserve("openai","fixture",100))).isInstanceOf(IllegalStateException.class).hasMessageContaining("账本");}
 @Test void circuitOpensForThreeFailuresAndIsAccountScoped(){var g=create(2,2,10,2000);try(var scope=UserContext.open(a)){for(int i=0;i<3;i++){var l=g.reserve("openai","fixture",100);g.finish(l,null,null,"FAILED");}assertThatThrownBy(()->g.reserve("openai","fixture",100)).isInstanceOf(ModelGovernance.Denied.class).hasMessageContaining("熔断");}UserContext.call(b,()->g.reserve("openai","fixture",100));}
 @Test void wrapperLimitsOutputAndKeepsMeasuredUsage(){var g=create(2,2,10,10000);AtomicInteger max=new AtomicInteger();ChatModel model=g.govern(prompt->{max.set(prompt.getOptions().getMaxTokens());return response(12,4);},"openai","fixture");try(var scope=UserContext.open(a)){model.call(new Prompt("private text",ChatOptions.builder().maxTokens(9000).build()));assertThat(max).hasValue(128);assertThat(g.summary().knownTokens()).isEqualTo(16);assertThat(g.summary().active()).isZero();assertThat(g.events().getFirst().costStatus()).isEqualTo("UNKNOWN");}}
 @Test void wrapperRecordsUnknownAndDoesNotRetryFailures(){var g=create(2,2,10,10000);AtomicInteger calls=new AtomicInteger();ChatModel model=g.govern(prompt->{calls.incrementAndGet();throw new IllegalStateException("fixture");},"openai","fixture");try(var scope=UserContext.open(a)){assertThatThrownBy(()->model.call(new Prompt("private text"))).isInstanceOf(IllegalStateException.class);assertThat(calls).hasValue(1);assertThat(g.summary().active()).isZero();assertThat(g.events().getFirst().inputTokens()).isNull();assertThat(g.summary().budgetChargedTokens()).isPositive();}}
 @Test void streamCapturesIdentityUsesFinalCumulativeUsageAndReleases(){var g=create(2,2,10,10000);ChatModel delegate=new ChatModel(){public ChatResponse call(Prompt p){return response(1,1);}public Flux<ChatResponse> stream(Prompt p){return Flux.just(response(5,1),response(5,3));}};Flux<ChatResponse> stream;try(var scope=UserContext.open(a)){stream=g.govern(delegate,"openai","fixture").stream(new Prompt("hello"));}assertThat(stream.collectList().block()).hasSize(2);try(var scope=UserContext.open(a)){assertThat(g.summary().knownTokens()).isEqualTo(8);assertThat(g.summary().active()).isZero();}}
 @Test void streamCancellationAndSynchronousSetupFailureReleaseLease(){var g=create(2,2,10,10000);ChatModel never=new ChatModel(){public ChatResponse call(Prompt p){return response(1,1);}public Flux<ChatResponse> stream(Prompt p){return Flux.concat(Flux.just(response(5,1)),Flux.never());}};try(var scope=UserContext.open(a)){g.govern(never,"openai","fixture").stream(new Prompt("hello")).take(1).blockLast();assertThat(g.events().getFirst().status()).isEqualTo("CANCELLED");assertThat(g.summary().active()).isZero();ChatModel bad=new ChatModel(){public ChatResponse call(Prompt p){throw new IllegalStateException();}public Flux<ChatResponse> stream(Prompt p){throw new IllegalStateException();}};assertThatThrownBy(()->g.govern(bad,"openai","fixture").stream(new Prompt("hello")).blockLast()).isInstanceOf(IllegalStateException.class);assertThat(g.summary().active()).isZero();}}
 @Test void duplicateCompletionIsIdempotentAndLedgerContainsNoPromptsOrUrls()throws Exception{var g=create(2,2,10,1000);try(var scope=UserContext.open(a)){var lease=g.reserve("https://private-host/key","model with secret",100);g.finish(lease,2L,3L,"SUCCEEDED");g.finish(lease,200L,300L,"SUCCEEDED");assertThat(g.summary().knownTokens()).isEqualTo(5);String raw=Files.readString(dir.resolve(a.id()).resolve("2026-10-20.json"));assertThat(raw).doesNotContain("private-host","model with secret").contains("custom","UNKNOWN");}}
 @Test void recordsOnlyValidatedRequestCorrelation(){var g=create(2,2,10,1000);try(var scope=UserContext.open(a)){try{org.slf4j.MDC.put("requestId","a".repeat(32));var lease=g.reserve("openai","fixture",100);g.finish(lease,1L,1L,"SUCCEEDED");assertThat(g.events().getFirst().requestId()).isEqualTo("a".repeat(32));org.slf4j.MDC.put("requestId","private text");g.reserve("openai","fixture",100);assertThat(g.events().getFirst().requestId()).isNull();}finally{org.slf4j.MDC.remove("requestId");}}}

 org.springframework.ai.tool.ToolCallback echo(AtomicInteger count,boolean direct){return new org.springframework.ai.tool.ToolCallback(){public org.springframework.ai.tool.definition.ToolDefinition getToolDefinition(){return org.springframework.ai.tool.definition.ToolDefinition.builder().name("echo").description("fixture").inputSchema("{\"type\":\"object\",\"properties\":{}}").build();}public String call(String input){assertThat(UserContext.current()).isEqualTo(a);count.incrementAndGet();return "evidence";}public org.springframework.ai.tool.metadata.ToolMetadata getToolMetadata(){return org.springframework.ai.tool.metadata.ToolMetadata.builder().returnDirect(direct).build();}};}
 ChatResponse toolResponse(){return new ChatResponse(List.of(new Generation(new AssistantMessage("",Map.of(),List.of(new AssistantMessage.ToolCall("t1","function","echo","{}"))))),ChatResponseMetadata.builder().usage(new DefaultUsage(10,2)).build());}
 @Test void internalToolLoopUsesOneAdmissionPerModelRound(){var g=create(2,2,10,10000);AtomicInteger calls=new AtomicInteger(),tools=new AtomicInteger();ChatModel delegate=p->{assertThat(((org.springframework.ai.model.tool.ToolCallingChatOptions)p.getOptions()).getInternalToolExecutionEnabled()).isFalse();return calls.incrementAndGet()==1?toolResponse():response(20,5);};var options=org.springframework.ai.model.tool.ToolCallingChatOptions.builder().toolCallbacks(echo(tools,false)).build();try(var scope=UserContext.open(a)){assertThat(g.govern(delegate,"openai","fixture").call(new Prompt("use echo",options)).getResult().getOutput().getText()).isEqualTo("fixture");assertThat(calls).hasValue(2);assertThat(tools).hasValue(1);assertThat(g.summary().requests()).isEqualTo(2);assertThat(g.summary().knownTokens()).isEqualTo(37);}}
 @Test void internalToolLoopCannotIssueSecondRequestAfterDailyQuota(){var g=create(2,2,1,10000);AtomicInteger calls=new AtomicInteger(),tools=new AtomicInteger();ChatModel delegate=p->{calls.incrementAndGet();return toolResponse();};var options=org.springframework.ai.model.tool.ToolCallingChatOptions.builder().toolCallbacks(echo(tools,false)).build();try(var scope=UserContext.open(a)){assertThatThrownBy(()->g.govern(delegate,"openai","fixture").call(new Prompt("use echo",options))).isInstanceOf(ModelGovernance.Denied.class);assertThat(calls).hasValue(1);assertThat(tools).hasValue(1);}}
 @Test void returnDirectToolDoesNotIssueExtraModelCallAndStreamingUsesGovernedLoop(){var g=create(2,2,10,10000);AtomicInteger calls=new AtomicInteger(),tools=new AtomicInteger();ChatModel delegate=p->{calls.incrementAndGet();return toolResponse();};var options=org.springframework.ai.model.tool.ToolCallingChatOptions.builder().toolCallbacks(echo(tools,true)).build();Flux<ChatResponse> stream;try(var scope=UserContext.open(a)){stream=g.govern(delegate,"openai","fixture").stream(new Prompt("use echo",options));}assertThat(stream.blockLast().getResult().getOutput().getText()).contains("evidence");assertThat(calls).hasValue(1);assertThat(tools).hasValue(1);}
 @Test void externallyManagedToolLoopIsNotExecutedTwice(){var g=create(2,2,10,10000);AtomicInteger tools=new AtomicInteger();var options=org.springframework.ai.model.tool.ToolCallingChatOptions.builder().toolCallbacks(echo(tools,false)).internalToolExecutionEnabled(false).build();try(var scope=UserContext.open(a)){assertThat(g.govern(p->toolResponse(),"openai","fixture").call(new Prompt("use echo",options)).hasToolCalls()).isTrue();assertThat(tools).hasValue(0);assertThat(g.summary().requests()).isEqualTo(1);}}

 @Test void streamUsesAuthenticatedReactorContextWhenAssemblyHasNoThreadLocal(){var g=create(2,2,10,10000);ChatModel delegate=new ChatModel(){public ChatResponse call(Prompt p){return response(1,2);}public Flux<ChatResponse> stream(Prompt p){assertThat(UserContext.current()).isEqualTo(a);return Flux.just(response(1,2));}};var stream=g.govern(delegate,"openai","fixture").stream(new Prompt("hello"));assertThat(stream.contextWrite(c->c.put(UserContext.User.class,a).put("requestId","b".repeat(32))).blockLast()).isNotNull();try(var scope=UserContext.open(a)){assertThat(g.events().getFirst().requestId()).isEqualTo("b".repeat(32));assertThat(g.summary().knownTokens()).isEqualTo(3);}assertThatThrownBy(()->stream.blockLast()).isInstanceOf(IllegalStateException.class).hasMessageContaining("authenticated");}

 @Test void failedCancelledAndUnknownPartialUsageNeverRefundReservations(){var g=create(2,2,10,10000);try(var scope=UserContext.open(a)){for(String status:List.of("FAILED","CANCELLED","UNKNOWN")){var lease=g.reserve("openai",status,1000);g.finish(lease,10L,0L,status);assertThat(g.events().getFirst().chargedTokens()).isEqualTo(1000);assertThat(g.events().getFirst().inputTokens()).isEqualTo(10);}assertThat(g.summary().knownTokens()).isEqualTo(30);assertThat(g.summary().budgetChargedTokens()).isEqualTo(3000);}}
 @Test void abortedStreamWithInitialUsageDoesNotReleaseConservativeQuota(){var g=create(2,2,10,10000);ChatModel delegate=new ChatModel(){public ChatResponse call(Prompt p){return response(1,1);}public Flux<ChatResponse> stream(Prompt p){return Flux.concat(Flux.just(response(10,0)),Flux.error(new IllegalStateException("disconnected")));}};try(var scope=UserContext.open(a)){assertThatThrownBy(()->g.govern(delegate,"anthropic","fixture").stream(new Prompt("hello")).blockLast()).isInstanceOf(IllegalStateException.class);var event=g.events().getFirst();assertThat(event.status()).isEqualTo("FAILED");assertThat(event.chargedTokens()).isEqualTo(event.reservedTokens()).isPositive();assertThat(g.summary().active()).isZero();}}
 @Test void successfulUntrustedZeroUsageCannotRefundBudgetAndOverageIsCharged(){var g=create(2,2,10,10000);try(var scope=UserContext.open(a)){var lease=g.reserve("custom","fixture",1000);g.finish(lease,0L,0L,"SUCCEEDED");assertThat(g.summary().knownTokens()).isZero();assertThat(g.summary().budgetChargedTokens()).isEqualTo(1000);var next=g.reserve("custom","fixture",1000);g.finish(next,2000L,100L,"SUCCEEDED");assertThat(g.events().getFirst().chargedTokens()).isEqualTo(2100);assertThat(g.summary().budgetChargedTokens()).isEqualTo(3100);}}

 @Test void failedSettlementBlocksNewCallsAndOnlyRetriesDiskAfterRecovery()throws Exception{var g=create(1,2,10,10000);ModelGovernance.Lease lease;try(var scope=UserContext.open(a)){lease=g.reserve("openai","fixture",1000);}Path owner=dir.resolve(a.id()),backup=dir.resolve("saved-owner");Files.move(owner,backup);Files.writeString(owner,"temporarily unavailable directory");assertThatThrownBy(()->g.finish(lease,10L,5L,"SUCCEEDED")).isInstanceOf(IllegalStateException.class).hasMessageContaining("账本");assertThatThrownBy(()->UserContext.call(b,()->g.reserve("openai","fixture",1000))).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->UserContext.call(a,g::summary)).isInstanceOf(IllegalStateException.class);Files.delete(owner);Files.move(backup,owner);try(var scope=UserContext.open(a)){assertThat(g.summary().active()).isZero();assertThat(g.summary().requests()).isEqualTo(1);assertThat(g.summary().knownTokens()).isEqualTo(15);assertThat(g.summary().budgetChargedTokens()).isEqualTo(1000);assertThat(g.events().getFirst().status()).isEqualTo("SUCCEEDED");g.finish(lease,999L,999L,"FAILED");assertThat(g.summary().knownTokens()).isEqualTo(15);g.reserve("openai","fixture",1000);}try(var scope=UserContext.open(b)){assertThat(g.summary().requests()).isZero();}}

 @Test void providerErrorBodiesCannotEscapeGovernedCallOrStream(){var g=create(2,2,10,10000);ChatModel delegate=new ChatModel(){public ChatResponse call(Prompt p){throw new IllegalStateException("private-provider-body",new RuntimeException("private-credential"));}public Flux<ChatResponse> stream(Prompt p){return Flux.error(new IllegalStateException("private-provider-body"));}};try(var scope=UserContext.open(a)){var model=g.govern(delegate,"openai","fixture");assertThatThrownBy(()->model.call(new Prompt("hello"))).isInstanceOf(IllegalStateException.class).hasNoCause().hasMessageNotContaining("private");assertThatThrownBy(()->model.stream(new Prompt("hello")).blockLast()).isInstanceOf(IllegalStateException.class).hasNoCause().hasMessageNotContaining("private");assertThat(g.summary().active()).isZero();}}

}
